require 'thread'
require 'logger'
require 'json'
require 'securerandom'

module SearchIndexer
  class IndexingService
    BATCH_SIZE = 100
    FLUSH_INTERVAL = 5

    def initialize(config = {})
      @logger = Logger.new(STDOUT)
      @logger.level = Logger::INFO
      @index_path = config.fetch(:index_path, '/var/lib/search/index')
      @buffer = []
      @buffer_mutex = Mutex.new
      @state = :initialized
      @checkpoint_file = File.join(@index_path, '.checkpoint')
      @stats = { indexed: 0, errors: 0, batches: 0 }
      @shutdown_requested = false
      @shutdown_pipe_r, @shutdown_pipe_w = IO.pipe
      @flush_thread = nil
      setup_signal_handlers
    end

    def start
      @state = :running
      @flush_thread = Thread.new { periodic_flush_loop }
      @shutdown_thread = Thread.new { shutdown_monitor_loop }
      @logger.info("IndexingService started, PID=#{Process.pid}")
    end

    def index_document(doc)
      return { status: :rejected, reason: :shutting_down } unless accepting_documents?

      validated = validate_and_sanitize(doc)
      return { status: :error, reason: :invalid_document } unless validated

      @buffer_mutex.synchronize do
        @buffer << validated
        if @buffer.size >= BATCH_SIZE
          flush_buffer_locked
        end
      end
      { status: :accepted, id: validated[:id] }
    end

    def status
      { state: @state, stats: @stats.dup, buffer_size: @buffer.size }
    end

    private

    def setup_signal_handlers
      Signal.trap('TERM') { @shutdown_pipe_w.write_nonblock("T") rescue nil }
      Signal.trap('INT') { @shutdown_pipe_w.write_nonblock("I") rescue nil }
      Signal.trap('USR1') { @shutdown_pipe_w.write_nonblock("R") rescue nil }
    end

    def shutdown_monitor_loop
      while @state == :running || @state == :draining
        ready = IO.select([@shutdown_pipe_r], nil, nil, 1)
        next unless ready

        cmd = @shutdown_pipe_r.read_nonblock(1) rescue nil
        case cmd
        when 'T', 'I'
          initiate_graceful_shutdown
        when 'R'
          rotate_checkpoint
        end
      end
    end

    def initiate_graceful_shutdown
      return if @shutdown_requested
      @shutdown_requested = true
      @logger.info("Shutdown initiated")
      drain_and_stop
    end

    def drain_and_stop
      @state = :draining
      flush_remaining
      write_checkpoint
      @state = :stopped
      cleanup_resources
    end

    def accepting_documents?
      @state == :running
    end

    def periodic_flush_loop
      while @state == :running || @state == :draining
        sleep FLUSH_INTERVAL
        @buffer_mutex.synchronize do
          flush_buffer_locked unless @buffer.empty?
        end
      end
    end

    def flush_remaining
      @buffer_mutex.synchronize do
        flush_buffer_locked unless @buffer.empty?
      end
    end

    def flush_buffer_locked
      batch = @buffer.dup
      @buffer.clear
      commit_batch(batch)
    end

    def commit_batch(batch)
      batch_id = SecureRandom.hex(8)
      @logger.info("Committing batch #{batch_id}, size=#{batch.size}")

      temp_path = File.join(@index_path, ".batch_#{batch_id}.tmp")
      final_path = File.join(@index_path, "batch_#{batch_id}.idx")

      File.open(temp_path, 'w') do |f|
        batch.each { |doc| f.puts(JSON.generate(doc)) }
        f.fsync
      end

      File.rename(temp_path, final_path)
      @stats[:indexed] += batch.size
      @stats[:batches] += 1
    rescue => e
      @stats[:errors] += batch.size
      @logger.error("Batch #{batch_id} failed: #{e.message}")
    end

    def write_checkpoint
      checkpoint_data = {
        timestamp: Time.now.iso8601,
        stats: @stats,
        state: @state.to_s,
        last_buffer_size: @buffer.size
      }
      tmp = "#{@checkpoint_file}.tmp"
      File.open(tmp, 'w') do |f|
        f.write(JSON.generate(checkpoint_data))
        f.fsync
      end
      File.rename(tmp, @checkpoint_file)
    end

    def rotate_checkpoint
      backup = "#{@checkpoint_file}.#{Time.now.to_i}"
      File.rename(@checkpoint_file, backup) if File.exist?(@checkpoint_file)
      write_checkpoint
    end

    def validate_and_sanitize(doc)
      return nil unless doc.is_a?(Hash)
      return nil unless doc[:content].is_a?(String) && doc[:content].size < 1_000_000
      return nil unless doc[:type].is_a?(String) && doc[:type].match?(/\A[a-z_]+\z/)

      {
        id: SecureRandom.uuid,
        content: doc[:content].encode('UTF-8', invalid: :replace, undef: :replace),
        type: doc[:type],
        indexed_at: Time.now.iso8601
      }
    end

    def cleanup_resources
      @flush_thread&.kill
      @shutdown_pipe_r.close rescue nil
      @shutdown_pipe_w.close rescue nil
      @logger.info("IndexingService stopped cleanly")
    end
  end
end
